wget -qO- https://botan.randombit.net/releases/Botan-2.12.1.tar.xz | tar xvJ
cd Botan-2.12.1
./configure.py --prefix=/usr --cc-bin=$CXX --cc-abi-flags="$CXXFLAGS"                --disable-modules=locking_allocator                --unsafe-fuzzer-mode --build-fuzzers=libfuzzer                --with-fuzzer-lib='FuzzingEngine'
make
make install
cd ..
mkdir rnp-build
cd rnp-build
cmake     -DENABLE_SANITIZERS=0     -DENABLE_FUZZERS=1     -DCMAKE_C_COMPILER=$CC     -DCMAKE_CXX_COMPILER=$CXX     -DCMAKE_C_LINK_EXECUTABLE="$CXX <FLAGS> <CMAKE_C_LINK_FLAGS> <LINK_FLAGS> <OBJECTS>  -o <TARGET> <LINK_LIBRARIES>"     -DCMAKE_INSTALL_PREFIX=/usr     -DBUILD_SHARED_LIBS=on     -DBUILD_TESTING=off     -DCMAKE_VERBOSE_MAKEFILE:BOOL=ON     ../rnp/
make
FUZZERS="fuzz_dump fuzz_keyring"
for f in $FUZZERS; do
    cp src/fuzzing/$f "${OUT}/"
    chrpath -r '$ORIGIN/lib' "${OUT}/$f"
done
mkdir -p "${OUT}/lib"
cp src/lib/librnp-0.so.0 "${OUT}/lib/"
cp /usr/lib/libbotan-2.so.12 "${OUT}/lib/"
cp /lib/x86_64-linux-gnu/libjson-c.so.2 "${OUT}/lib/"
./afl/.travis/check_fuzzer_stats.sh
